import{_ as a,o,c,a2 as t}from"./chunks/framework.CiKk3sJz.js";const u=JSON.parse('{"title":"漫画 · 第 29 话 @scope：圈地、挖洞、近距优先","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.29-scope.md","filePath":"comics/css/EP.29-scope.md","lastUpdated":1792579602000}'),s={name:"comics/css/EP.29-scope.md"};function r(d,e,l,i,n,p){return o(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="漫画-·-第-29-话-scope-圈地、挖洞、近距优先" tabindex="-1">漫画 · 第 29 话 @scope：圈地、挖洞、近距优先 <a class="header-anchor" href="#漫画-·-第-29-话-scope-圈地、挖洞、近距优先" aria-label="Permalink to &quot;漫画 · 第 29 话 @scope：圈地、挖洞、近距优先&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/19-scope">docs/css/19-scope.md</a> ｜ 原画：<a href="./EP.29-scope.svg">EP.29-scope.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。给老后台系统接入新组件库，组件里的 <code>.title</code> 被全局上古规则污染，试过提特异性（再包一层又输回去）、Shadow DOM（把主题变量也挡在门外），进退两难。</li><li><strong>标签君</strong>：HTML5 结构师，搬出 <code>@scope</code>——规则只在圈内生效，<code>to</code> 挖出甜甜圈洞，两个圈打架时「谁离得近听谁的」。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>嵌套章（EP.28）收拢了「书写结构」，但像素酱发现嵌套只是把选择器写短，匹配范围仍然是全局的——样式照样泄漏。本话补上「作用域」这块拼图：<code>@scope</code> 给样式圈一块地盘，配合层叠层（EP.23）和嵌套（EP.28），「现代 CSS 架构」三部曲成型。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>全局样式里的 <code>.title</code>、<code>a</code> 等上古规则无差别命中新组件。已有方案各有短板：提特异性是军备竞赛，Shadow DOM 隔离太彻底（字体、CSS 变量进不去），CSS Modules 绑死构建链。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p><code>@scope (.card) { img {} }</code> 圈定子树，<code>@scope (.article) to (.widget)</code> 挖出甜甜圈洞——<code>.widget</code> 整棵子树免疫。两个作用域同时命中时启用「近距优先」：DOM 上离元素更近的根获胜，不比特异性不比书写顺序。关键细节：根选择器不参与特异性计算，<code>@scope (#app) { .btn {} }</code> 特异性仍是 (0,1,0)。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>四大实战场景：组件样式圈地（BEM 长名瘦身回 <code>.title</code>）、富文本甜甜圈（排版规则绕开嵌入组件）、主题区域接管（两个主题并存互不污染）、第三方微件隔离（宿主页面零冲突，字体与变量照常继承）。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>@scope （根） to （限界）：圈内生效、甜甜圈挖洞，根选择器不抬特异性。</li><li>近距优先：两个作用域同时命中时，DOM 上更近的根获胜。</li><li>它不是 Shadow DOM：是低成本圈地，不是硬隔离，主题变量照常继承。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：<code>@scope (#app) { .btn { color: red; } }</code> 和手写 <code>#app .btn { color: red; }</code>，特异性一样吗？哪个更容易被业务方覆盖？</p><p><strong>答</strong>：不一样。手写 <code>#app .btn</code> 特异性是 (1,1,0)（ID + 类），业务方要覆盖得写出更高特异性或同级更靠后的规则。<code>@scope (#app) { .btn {} }</code> 中根选择器不计入特异性，内部规则只有 (0,1,0)——业务方一条 <code>.btn { color: blue }</code> 同级规则按书写顺序即可覆盖。这正是 @scope 适合组件库的原因：<strong>隔离命中范围，但不制造特异性霸权</strong>。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>组件圈地 + 甜甜圈富文本 + 双主题并存 + 近距优先嵌套：<a href="./../../examples/css/19-scope/index-01-scope.html">examples/css/19-scope/</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 30 话《@property》——给 CSS 变量上户口：syntax/inherits/initial-value 三件套注册后，颜色过渡不再跳变，角度百分比皆可补间。</p>',22)])])}const b=a(s,[["render",r]]);export{u as __pageData,b as default};
